sys_script_include.script:
var RescheduleHelper = Class.create();
RescheduleHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
 rescheduleEvent: function() {
        var eventId = this.getParameter('sysparm_eventId');
        var newDateInput = this.getParameter('sysparm_newDate');

        if (newDateInput.length == 10) {
            newDateInput += " 09:00:00";
        }

        var gr = new GlideRecord('x_1790229_event_ma_event_record');
        if (gr.get(eventId)) {
            gr.u_event_date = newDateInput;
            gr.update();

            // Notify Planner
            gs.eventQueue('x_1790229_event_ma.notify.planner', gr, gr.u_planer, gr.sys_id);

            return 'success';
        }
        return 'failure';
    },

    type: 'RescheduleHelper'
});
